+// Converts a Julian Ephemeris Day (Terrestrial Time) to a UTC QDateTime
+inline QDateTime ephemerisDayToDateTime(double jde)
+{
+    // Difference between Terrestrial Time and UTC, using Espenak and Meeus' polynomial,
+    // which is good to about a minute for the years 1950 to 2100
+    const double t = (jde - 2451545.0) / 365.25;
+    const double deltaT = 62.92 + 0.32217 * t + 0.005589 * t * t;
+    const qint64 msecs = std::llround((jde - 2440587.5) * 86400000.0 - deltaT * 1000.0);
+    return QDateTime::fromMSecsSinceEpoch(msecs, QTimeZone::UTC);
+}
+}
