+/*
+    Times of the principal phases, from Astronomical Algorithms by Jean Meeus, chapter 49.
+    lunation 0 is the new moon of 2000 January 6, quarter is 0 to 3 for new moon, first quarter,
+    full moon and last quarter.
+*/
+static double phaseJDE(int lunation, int quarter)
+{
+    const double k = lunation + quarter / 4.0;
+    const double T = k / 1236.85;
+    const double T2 = T * T;
+    const double T3 = T2 * T;
+    const double T4 = T3 * T;
+
+    double jde = 2451550.09766 + 29.530588861 * k + 0.00015437 * T2 - 0.000000150 * T3 + 0.00000000073 * T4;
+
+    const double E = 1 - 0.002516 * T - 0.0000074 * T2;
+    const double M = degToRad(2.5534 + 29.10535670 * k - 0.0000014 * T2 - 0.00000011 * T3);
+    const double Mp = degToRad(201.5643 + 385.81693528 * k + 0.0107582 * T2 + 0.00001238 * T3 - 0.000000058 * T4);
+    const double F = degToRad(160.7108 + 390.67050284 * k - 0.0016118 * T2 - 0.00000227 * T3 + 0.000000011 * T4);
+    const double Omega = degToRad(124.7746 - 1.56375588 * k + 0.0020672 * T2 + 0.00000215 * T3);
+
+    if (quarter == 0 || quarter == 2) {
+        const bool isNew = quarter == 0;
+        jde += (isNew ? -0.40720 : -0.40614) * sin(Mp) //
+            + (isNew ? 0.17241 : 0.17302) * E * sin(M) //
+            + (isNew ? 0.01608 : 0.01614) * sin(2 * Mp) //
+            + (isNew ? 0.01039 : 0.01043) * sin(2 * F) //
+            + (isNew ? 0.00739 : 0.00734) * E * sin(Mp - M) //
+            + (isNew ? -0.00514 : -0.00515) * E * sin(Mp + M) //
+            + (isNew ? 0.00208 : 0.00209) * E * E * sin(2 * M) //
+            - 0.00111 * sin(Mp - 2 * F) //
+            - 0.00057 * sin(Mp + 2 * F) //
+            + 0.00056 * E * sin(2 * Mp + M) //
+            - 0.00042 * sin(3 * Mp) //
+            + 0.00042 * E * sin(M + 2 * F) //
+            + 0.00038 * E * sin(M - 2 * F) //
+            - 0.00024 * E * sin(2 * Mp - M) //
+            - 0.00017 * sin(Omega) //
+            - 0.00007 * sin(Mp + 2 * M) //
+            + 0.00004 * sin(2 * Mp - 2 * F) //
+            + 0.00004 * sin(3 * M) //
+            + 0.00003 * sin(Mp + M - 2 * F) //
+            + 0.00003 * sin(2 * Mp + 2 * F) //
+            - 0.00003 * sin(Mp + M + 2 * F) //
+            + 0.00003 * sin(Mp - M + 2 * F) //
+            - 0.00002 * sin(Mp - M - 2 * F) //
+            - 0.00002 * sin(3 * Mp + M) //
+            + 0.00002 * sin(4 * Mp);
+    } else {
+        jde += -0.62801 * sin(Mp) //
+            + 0.17172 * E * sin(M) //
+            - 0.01183 * E * sin(Mp + M) //
+            + 0.00862 * sin(2 * Mp) //
+            + 0.00804 * sin(2 * F) //
+            + 0.00454 * E * sin(Mp - M) //
+            + 0.00204 * E * E * sin(2 * M) //
+            - 0.00180 * sin(Mp - 2 * F) //
+            - 0.00070 * sin(Mp + 2 * F) //
+            - 0.00040 * sin(3 * Mp) //
+            - 0.00034 * E * sin(2 * Mp - M) //
+            + 0.00032 * E * sin(M + 2 * F) //
+            + 0.00032 * E * sin(M - 2 * F) //
+            - 0.00028 * E * E * sin(Mp + 2 * M) //
+            + 0.00027 * E * sin(2 * Mp + M) //
+            - 0.00017 * sin(Omega) //
+            - 0.00005 * sin(Mp - M - 2 * F) //
+            + 0.00004 * sin(2 * Mp + 2 * F) //
+            - 0.00004 * sin(Mp + M + 2 * F) //
+            + 0.00004 * sin(Mp - 2 * M) //
+            + 0.00003 * sin(Mp + M - 2 * F) //
+            + 0.00003 * sin(3 * M) //
+            + 0.00002 * sin(2 * Mp - 2 * F) //
+            + 0.00002 * sin(Mp - M + 2 * F) //
+            - 0.00002 * sin(3 * Mp + M);
+
+        const double W = 0.00306 - 0.00038 * E * cos(M) + 0.00026 * cos(Mp) - 0.00002 * cos(Mp - M) + 0.00002 * cos(Mp + M) + 0.00002 * cos(2 * F);
+        jde += quarter == 1 ? W : -W;
+    }
+
+    jde += 0.000325 * sin(degToRad(299.77 + 0.107408 * k - 0.009173 * T2));
+
+    struct Planetary {
+        double coefficient;
+        double base;
+        double perLunation;
+    };
+    // clang-format off
+    const Planetary planetary[] = {
+        {0.000165, 251.88,  0.016321}, {0.000164, 251.83, 26.651886}, {0.000126, 349.42, 36.412478},
+        {0.000110,  84.66, 18.206239}, {0.000062, 141.74, 53.303771}, {0.000060, 207.14,  2.453732},
+        {0.000056, 154.84,  7.306860}, {0.000047,  34.52, 27.261239}, {0.000042, 207.19,  0.121824},
+        {0.000040, 291.34,  1.844379}, {0.000037, 161.72, 24.198154}, {0.000035, 239.56, 25.513099},
+        {0.000023, 331.55,  3.592518},
+    };
+    // clang-format on
+    for (const Planetary &p : planetary) {
+        jde += p.coefficient * sin(degToRad(p.base + p.perLunation * k));
+    }
+
+    return jde;
+}
+
+static std::pair<LunarPhase::Phase, QDateTime> principalPhaseBetween(const QDateTime &start, const QDateTime &end)
+{
+    static const LunarPhase::Phase phases[] = {LunarPhase::NewMoon, LunarPhase::FirstQuarter, LunarPhase::FullMoon, LunarPhase::LastQuarter};
+
+    // Principal phases are about 7.4 days apart, so only the ones around start can fall before end
+    const double startJD = start.toMSecsSinceEpoch() / 86400000.0 + 2440587.5;
+    const int startQuarter = static_cast<int>(std::floor((startJD - 2451550.09766) / 29.530588861 * 4));
+    for (int q = startQuarter - 1; q <= startQuarter + 2; ++q) {
+        const int lunation = static_cast<int>(std::floor(q / 4.0));
+        const int quarter = q - lunation * 4;
+        const QDateTime moment = ephemerisDayToDateTime(phaseJDE(lunation, quarter));
+        if (moment >= start && moment < end) {
+            return {phases[quarter], moment};
+        }
+    }
+    return {LunarPhase::None, QDateTime()};
+}
